{"command":"create","path":"/workspace/d_flip_flop_tb.v","file_text":"`timescale 1ns/1ps

module d_flip_flop_tb;
    reg clk;
    reg reset;
    reg d;
    wire q;

    d_flip_flop uut (
        .clk(clk),
        .reset(reset),
        .d(d),
        .q(q)
    );

    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        $monitor("Time=%0t | clk=%b | reset=%b | d=%b | q=%b", $time, clk, reset, d, q);

        // Test sequence
        reset = 1; d = 0;
        #10 reset = 0; d = 1;
        #10 d = 0;
        #10 d = 1;
        #10 reset = 1;
        #10 reset = 0; d = 0;
        #10 d = 1;
        #10 $finish;
    end

    // Assertions
    always @(posedge clk) begin
        if (reset) begin
            if (q !== 0) begin
                $display("Assertion failed: q should be 0 when reset is active");
                $stop;
            end
        end else begin
            if (q !== d) begin
                $display("Assertion failed: q should follow d when reset is inactive");
                $stop;
            end
        end
    end

endmodule"}

